# (model, field) pairs whose existing files move from public media/ into
# media/private/. Relative names are kept, so no DB rows change.
PRIVATE_FIELDS = [
    ('EmployeeDocument', 'file'),
    ('GuarantorDocument', 'file'),
    ('LeaveRequest', 'supporting_documents'),
    ('Payslip', 'pdf_file'),
]


def _names(apps):
    for model_name, field in PRIVATE_FIELDS:
        Model = apps.get_model('hr', model_name)
        # _base_manager: include soft-deleted rows too; iterator(): constant memory.
        qs = Model._base_manager.exclude(**{field: ''}).exclude(**{f'{field}__isnull': True})
        yield from qs.values_list(field, flat=True).iterator(chunk_size=500)


def move_existing_files(apps, schema_editor):
    from common.private_files import move_to_private
    moved = sum(1 for name in _names(apps) if move_to_private(name))
    if moved:
        print(f'\n  moved {moved} HR file(s) into private storage')


def move_files_back(apps, schema_editor):
    from pathlib import Path
    from django.conf import settings
    from common.private_files import private_root
    for name in _names(apps):
        src, dst = private_root() / name, Path(settings.MEDIA_ROOT) / name
        if src.is_file() and not dst.exists():
            dst.parent.mkdir(parents=True, exist_ok=True)
            src.replace(dst)


